/* @autogenerated */
package net.civeira.phylax.features.oauth.user.infrastructure.driven;

import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.temporal.TemporalAmount;
import java.util.Optional;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.user.domain.gateway.UserWriteRepositoryGateway;
import net.civeira.phylax.features.access.useraccesstemporalcode.domain.UserAccessTemporalCode;
import net.civeira.phylax.features.access.useraccesstemporalcode.domain.UserAccessTemporalCodeChangeSet;
import net.civeira.phylax.features.access.useraccesstemporalcode.domain.gateway.UserAccessTemporalCodeFilter;
import net.civeira.phylax.features.access.useraccesstemporalcode.domain.gateway.UserAccessTemporalCodeWriteRepositoryGateway;
import net.civeira.phylax.features.oauth.authentication.application.service.SecureCodeGenerator;
import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.user.domain.RecoveryNotificationData;
import net.civeira.phylax.features.oauth.user.domain.gateway.ChangePasswordGateway;
import net.civeira.phylax.features.oauth.user.infrastructure.ActiveUserFindService;
import net.civeira.phylax.features.oauth.user.infrastructure.UserLoginService;

@Transactional
@ApplicationScoped
@RequiredArgsConstructor
public class ChangePasswordAdapter implements ChangePasswordGateway {
  private final static TemporalAmount RECOVER_TIME = Duration.ofHours(12);

  private final ActiveUserFindService activeUser;
  private final UserWriteRepositoryGateway users;
  private final UserAccessTemporalCodeWriteRepositoryGateway codes;
  private final UserLoginService loginUsecase;

  @Override
  public boolean allowRecover(String tenant) {
    return true;
  }

  @Override
  public Optional<RecoveryNotificationData> requestForChange(String urlBase, String tenant,
      String username) {
    AuthRequest request = AuthRequest.builder().tenant(tenant).build();
    recover(request, username, urlBase);
    // Notification is handled internally by PasswordRecoverUsecase - no data to return.
    return Optional.empty();
  }

  @Override
  public Optional<String> validateChangeRequest(String tenant, String username, String code,
      String newPassword) {
    AuthRequest request = AuthRequest.builder().tenant(tenant).build();
    return checkRecoverCode(request, username, code, newPassword);
  }

  @Override
  public boolean forceUpdatePassword(String tenant, String username, String oldPassword,
      String newPassword) {
    AuthRequest request = AuthRequest.builder().tenant(tenant).build();
    return loginUsecase.updatePassword(request, username, oldPassword, newPassword);
  }

  private Optional<String> checkRecoverCode(AuthRequest request, String email, String code,
      String newPassoword) {
    return activeUser
        .findEnabledUserByNameOrEmail(request.getTenant(), email, request.getAudiences())
        .flatMap(user -> {
          if (user.getProvider().isPresent()) {
            return Optional.empty();
          }
          Optional<UserAccessTemporalCode> find =
              codes.findForUpdate(UserAccessTemporalCodeFilter.builder().user(user).build());
          if (!find.isPresent()) {
            return Optional.empty();
          }
          UserAccessTemporalCode tempCode = find.get();
          if (!"".equals(code) && code.equals(tempCode.getRecoveryCode().orElse(""))) {
            codes.update(tempCode, tempCode.resetPasswordRecover());
            // codes.update(tempCode, tempCode.withNullRecoveryCode());
            users.update(user, user.changePassword(newPassoword));
            // users.update(user, user.withPlainPassword(newPassoword));
            return Optional.of(user.getName());
          } else {
            return Optional.empty();
          }
        });
  }

  private void recover(AuthRequest request, String email, String urlWithParams) {
    activeUser.findEnabledUserByNameOrEmail(request.getTenant(), email, request.getAudiences())
        .ifPresent(user -> {
          if (user.getProvider().isPresent()) {
            return;
          }
          String code = SecureCodeGenerator.generate();
          Optional<UserAccessTemporalCode> find =
              codes.findForUpdate(UserAccessTemporalCodeFilter.builder().user(user).build());
          UserAccessTemporalCode userCode;
          if (find.isPresent()) {
            userCode = find.get();
          } else {
            userCode = codes.create(
                UserAccessTemporalCode.create(new UserAccessTemporalCodeChangeSet().newUid()));
          }
          codes.update(userCode, userCode.generatePasswordRecover(urlWithParams, code,
              OffsetDateTime.now().plus(RECOVER_TIME)));
        });
  }

}
